"use client";

import { useId, useState } from "react";

import { Button } from "@/components/ui/button";

import { CalendarIcon, CheckIcon } from "../parts/icons";
import { BlockFrame } from "../parts/block-frame";
import { RollingText } from "../parts/rolling-text";
import { formatWhole } from "../lib/format";
import { LinkIcon, PinIcon, ShareIcon } from "./icons";
import { CoverArt } from "./profile-page/cover-art";
import { HANDLE, type ProfileFields, START_PROFILE, STATS } from "./profile-page/data";
import { EditSheet } from "./profile-page/edit-sheet";
import { Glow } from "./profile-page/glow";
import { ProfileTabs } from "./profile-page/profile-tabs";
import { PersonAvatar } from "./shared/person-avatar";

type Pulses = Record<keyof ProfileFields, number>;

const FIELD_KEYS = ["name", "title", "bio", "place", "site"] satisfies (keyof ProfileFields)[];

const NO_PULSE = { name: 0, title: 0, bio: 0, place: 0, site: 0 } satisfies Pulses;

/**
 * A practitioner's profile: cover art, avatar, name and role, a bio, where
 * they work, three figures, and tabs for activity and projects. Edit profile
 * opens a sheet; saved fields glow once on the page.
 */
export function ProfilePage({ className }: { className?: string }) {
  const titleId = useId();
  const [profile, setProfile] = useState(START_PROFILE);
  const [pulses, setPulses] = useState<Pulses>(NO_PULSE);
  const [shared, setShared] = useState(false);
  const [status, setStatus] = useState("");

  const save = (next: ProfileFields) => {
    const changed = FIELD_KEYS.filter((key) => next[key] !== profile[key]);
    setProfile(next);
    setPulses((current) => {
      const updated = { ...current };
      for (const key of changed) updated[key] += 1;
      return updated;
    });
    setStatus(changed.length ? `Profile saved. ${changed.length} ${changed.length === 1 ? "field" : "fields"} changed.` : "Profile saved with no changes.");
  };

  const share = async () => {
    try {
      await navigator.clipboard.writeText(`https://${profile.site}`);
      setShared(true);
      setStatus("Profile link copied.");
    } catch {
      setStatus(`Share this link: https://${profile.site}`);
    }
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <CoverArt />
      <div className="flex flex-col gap-4 px-5 pb-5">
        <div className="flex flex-wrap items-end justify-between gap-3">
          <PersonAvatar name={profile.name} hue={2} size="lg" ring className="-mt-10 rounded-full ring-4 ring-card" />
          <div className="flex items-center gap-2">
            <Button variant="outline" size="sm" onClick={share}>
              {shared ? <CheckIcon aria-hidden="true" className="size-4" /> : <ShareIcon aria-hidden="true" className="size-4" />}
              {shared ? "Link copied" : "Share"}
            </Button>
            <EditSheet profile={profile} onSave={save} />
          </div>
        </div>

        <div className="flex flex-col gap-1">
          <h2 id={titleId} className="text-xl font-semibold">
            <Glow pulse={pulses.name}>{profile.name}</Glow>
          </h2>
          <p className="text-sm text-muted-foreground">
            {HANDLE}, <Glow pulse={pulses.title}>{profile.title}</Glow>
          </p>
        </div>

        <p className="max-w-prose text-sm text-pretty">
          <Glow pulse={pulses.bio}>{profile.bio}</Glow>
        </p>

        <ul className="flex flex-wrap gap-x-5 gap-y-2 text-sm text-muted-foreground">
          <li className="flex items-center gap-1.5">
            <PinIcon aria-hidden="true" className="size-4" />
            <Glow pulse={pulses.place}>{profile.place}</Glow>
          </li>
          <li className="flex items-center gap-1.5">
            <LinkIcon aria-hidden="true" className="size-4" />
            <Glow pulse={pulses.site}>
              <Button variant="link" size="sm" asChild>
                <a href={`https://${profile.site}`} target="_blank" rel="noreferrer">
                  {profile.site}
                </a>
              </Button>
            </Glow>
          </li>
          <li className="flex items-center gap-1.5">
            <CalendarIcon aria-hidden="true" className="size-4" />
            Joined March 2021
          </li>
        </ul>

        <dl className="grid grid-cols-3 gap-px overflow-hidden rounded-xl border border-border bg-border">
          {STATS.map((stat) => (
            <div key={stat.label} className="flex flex-col gap-0.5 bg-card px-3 py-3">
              <dt className="text-xs text-muted-foreground">{stat.label}</dt>
              <dd className="text-lg font-semibold">
                <RollingText text={formatWhole(stat.value)} />
              </dd>
            </div>
          ))}
        </dl>
      </div>
      <ProfileTabs />
      <p aria-live="polite" className="sr-only">
        {status}
      </p>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

