"use client";

import { useId, useState } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Sheet, SheetContent, SheetDescription, SheetTitle, SheetTrigger } from "@/components/ui/sheet";
import { Textarea } from "@/components/ui/textarea";

import { PenIcon } from "../icons";
import type { ProfileFields } from "./data";

const FIELDS: { key: keyof ProfileFields; label: string; multiline?: boolean }[] = [
  { key: "name", label: "Name" },
  { key: "title", label: "Role" },
  { key: "bio", label: "Bio", multiline: true },
  { key: "place", label: "Where you work" },
  { key: "site", label: "Website" },
];

/** Props for the edit sheet. `onSave` receives the whole edited profile. */
export interface EditSheetProps {
  profile: ProfileFields;
  onSave: (next: ProfileFields) => void;
}

/**
 * Edit profile, in a sheet that slides in from the right. Enter saves from a
 * one-line field, Ctrl or Command with Enter saves from the bio, and Escape
 * closes without saving and returns focus to the Edit profile button.
 */
export function EditSheet({ profile, onSave }: EditSheetProps) {
  const id = useId();
  const [open, setOpen] = useState(false);
  const [draft, setDraft] = useState(profile);
  const [error, setError] = useState<string | null>(null);

  const save = () => {
    if (!draft.name.trim()) {
      setError("Your name cannot be empty.");
      return;
    }
    onSave({ ...draft, name: draft.name.trim() });
    setOpen(false);
  };

  return (
    <Sheet
      open={open}
      onOpenChange={(next) => {
        if (next) {
          setDraft(profile);
          setError(null);
        }
        setOpen(next);
      }}
    >
      <SheetTrigger asChild>
        <Button size="sm">
          <PenIcon aria-hidden="true" className="size-4" />
          Edit profile
        </Button>
      </SheetTrigger>
      <SheetContent side="right">
        <form
          noValidate
          className="flex h-full flex-col"
          onSubmit={(event) => {
            event.preventDefault();
            save();
          }}
        >
          <div className="flex flex-col gap-1.5 border-b border-border pr-8 pb-4">
            <SheetTitle>Edit profile</SheetTitle>
            <SheetDescription>Colleagues at every Fernhill clinic see this profile.</SheetDescription>
          </div>
          <div className="scroll-fade-effect-y scrollbar-none flex flex-1 flex-col gap-4 overflow-y-auto py-4">
            {FIELDS.map((field) => {
              const fieldId = `${id}-${field.key}`;
              const common = {
                id: fieldId,
                value: draft[field.key],
                "aria-invalid": field.key === "name" && error ? true : undefined,
                "aria-describedby": field.key === "name" && error ? `${id}-error` : undefined,
              };
              return (
                <div key={field.key} className="flex flex-col gap-1.5">
                  <label htmlFor={fieldId} className="text-sm font-medium">
                    {field.label}
                  </label>
                  {field.multiline ? (
                    <Textarea
                      {...common}
                      rows={4}
                      onChange={(event) => setDraft({ ...draft, [field.key]: event.target.value })}
                      onKeyDown={(event) => {
                        if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
                          event.preventDefault();
                          save();
                        }
                      }}
                    />
                  ) : (
                    <Input {...common} onChange={(event) => setDraft({ ...draft, [field.key]: event.target.value })} />
                  )}
                  {field.key === "name" && error ? (
                    <p id={`${id}-error`} className="text-sm text-destructive">
                      {error}
                    </p>
                  ) : null}
                </div>
              );
            })}
          </div>
          <div className="flex justify-end gap-2 border-t border-border pt-4">
            <Button type="button" variant="outline" onClick={() => setOpen(false)}>
              Cancel
            </Button>
            <Button type="submit">Save profile</Button>
          </div>
        </form>
      </SheetContent>
    </Sheet>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";

import { cn } from "@/lib/utils";

/** Props for a glow. `pulse` changes each time the wrapped field is saved with a new value; 0 means never. */
export interface GlowProps {
  pulse: number;
  children: ReactNode;
  className?: string;
}

/** Wraps a saved field and washes it once in the accent tint, so the change is easy to spot. */
export function Glow({ pulse, children, className }: GlowProps) {
  const reduce = useReducedMotion();
  return (
    <span className={cn("relative isolate inline-block rounded-md", className)}>
      {pulse > 0 ? (
        <motion.span
          key={pulse}
          aria-hidden="true"
          initial={{ opacity: 0 }}
          animate={{ opacity: [0, 1, 0] }}
          transition={{ duration: reduce ? 1.2 : 1.4, times: [0, 0.2, 1] }}
          className="absolute -inset-x-1.5 -inset-y-0.5 -z-10 rounded-md bg-chart-1/25"
        />
      ) : null}
      {children}
    </span>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import { useState } from "react";

import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { cn } from "@/lib/utils";

import { RollingText } from "../../parts/rolling-text";
import { StarIcon } from "../icons";
import { ACTIVITY, PROJECTS } from "./data";

const DOTS = [
  "bg-chart-1",
  "bg-chart-2",
  "bg-chart-3",
  "bg-chart-4",
  "bg-chart-5",
];

/** Activity and projects behind tabs whose underline travels. Projects can be starred. */
export function ProfileTabs() {
  const reduce = useReducedMotion();
  const [starred, setStarred] = useState<Set<string>>(new Set(["p2"]));
  const rise = {
    initial: { opacity: 0, y: reduce ? 0 : 6 },
    animate: { opacity: 1, y: 0 },
    transition: { duration: 0.2 },
  };

  const toggle = (id: string) =>
    setStarred((current) => {
      const next = new Set(current);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });

  return (
    <Tabs defaultValue="activity">
      <div className="px-5 pb-2">
        <TabsList className="w-full justify-start">
          <TabsTrigger value="activity">Activity</TabsTrigger>
          <TabsTrigger value="projects">
            Projects{" "}
            <span className="text-muted-foreground">{PROJECTS.length}</span>
          </TabsTrigger>
        </TabsList>
      </div>
      <TabsContent value="activity">
        <div className="px-5 pb-5">
          <motion.ol {...rise} className="flex flex-col">
            {ACTIVITY.map((item, index) => (
              <li key={item.id} className="relative flex gap-3 pb-4 last:pb-0">
                <span
                  aria-hidden="true"
                  className={cn(
                    "mt-1.5 size-2 shrink-0 rounded-full",
                    DOTS[index % 5],
                  )}
                />
                <div className="min-w-0">
                  <p className="text-sm">{item.text}</p>
                  <p className="text-xs text-muted-foreground">{item.when}</p>
                </div>
              </li>
            ))}
          </motion.ol>
        </div>
      </TabsContent>
      <TabsContent value="projects">
        <div className="px-5 pb-5">
          <motion.ul {...rise} className="grid gap-3 @xl:grid-cols-2">
            {PROJECTS.map((project) => {
              const on = starred.has(project.id);
              return (
                <li
                  key={project.id}
                  className="flex flex-col gap-2 rounded-xl border border-border p-4"
                >
                  <div className="flex items-start justify-between gap-2">
                    <h4 className="flex items-center gap-2 text-sm font-medium">
                      <span
                        aria-hidden="true"
                        className={cn(
                          "size-2.5 rounded-sm",
                          DOTS[project.hue - 1],
                        )}
                      />
                      {project.name}
                    </h4>
                    <Button
                      variant="ghost"
                      size="sm"
                      aria-pressed={on}
                      aria-label={`${on ? "Unstar" : "Star"} ${project.name}, ${project.stars + (on ? 1 : 0)} stars`}
                      onClick={() => toggle(project.id)}
                      className="-mt-1 -mr-2"
                    >
                      <StarIcon
                        aria-hidden="true"
                        className={cn(
                          "size-4",
                          on && "fill-current text-chart-4",
                        )}
                      />
                      <RollingText
                        text={String(project.stars + (on ? 1 : 0))}
                      />
                    </Button>
                  </div>
                  <p className="text-sm text-muted-foreground">
                    {project.line}
                  </p>
                </li>
              );
            })}
          </motion.ul>
        </div>
      </TabsContent>
    </Tabs>
  );
}

import { cn } from "@/lib/utils";

import { initials, type Presence } from "./roster";

const FILLS = ["bg-chart-1", "bg-chart-2", "bg-chart-3", "bg-chart-4", "bg-chart-5"];
const DOTS = { online: "bg-success", away: "bg-warning", offline: "bg-muted-foreground" } satisfies Record<Presence, string>;
const SIZES = { sm: "size-7 text-xs", md: "size-9 text-sm", lg: "size-20 text-2xl" };

/** Props for a person's avatar. The name sits beside it, so the avatar itself is hidden from screen readers. */
export interface PersonAvatarProps {
  name: string;
  hue: number;
  size?: keyof typeof SIZES;
  presence?: Presence;
  /** Draws a ring in the card colour, for avatars that overlap in a stack. */
  ring?: boolean;
  className?: string;
}

/** A round avatar: the person's initials on one of the five chart hues, with an optional presence dot. */
export function PersonAvatar({ name, hue, size = "md", presence, ring, className }: PersonAvatarProps) {
  return (
    <span aria-hidden="true" className={cn("relative inline-flex shrink-0", className)}>
      <span
        className={cn(
          "flex items-center justify-center rounded-full font-semibold text-primary-foreground select-none",
          FILLS[(hue - 1) % 5],
          SIZES[size],
          ring && "ring-2 ring-card",
        )}
      >
        {initials(name)}
      </span>
      {presence ? <span className={cn("absolute right-0 bottom-0 size-2.5 rounded-full ring-2 ring-card", DOTS[presence])} /> : null}
    </span>
  );
}

/** Which part of the clinic a person works in. */
export type Team = "Practitioners" | "Front desk" | "Operations";

/** Whether a person is around right now. */
export type Presence = "online" | "away" | "offline";

/** One person at Fernhill's Harbour Street clinic. Every name is invented. */
export interface Person {
  id: string;
  name: string;
  email: string;
  title: string;
  team: Team;
  /** Which of the five chart hues fills their avatar, 1 to 5. */
  hue: 1 | 2 | 3 | 4 | 5;
  presence: Presence;
  /** When they were last active, in words. */
  lastActive: string;
  place: string;
  bio: string;
  /** What they are working on this week. */
  focus: string;
}

const person = (
